// Get all tasks and find the first one that needs AI enhancement
const tasks = $input.first().json.result || [];

console.log(`Checking ${tasks.length} tasks`);

// Find first task needing enhancement
for (const task of tasks) {
  const description = task.description || '';
  const title = task.title || '';

  if (description.trim().length < 20 && title.trim().length > 0) {
    console.log(`Found task needing enhancement: "${title}" (ID: ${task.id})`);
    return {
      json: {
        task_id: task.id,
        title: title,
        description: description,
        project_id: task.project_id || 1
      }
    };
  }
}

// If no tasks need enhancement, return a skip signal
console.log('No tasks need enhancement');
return {
  json: {
    skip: true,
    message: 'No tasks need enhancement'
  }
};

