parameters.functionCode:
// Get task data and AI response
const taskData = $('Find Task to Enhance').first().json;
const aiResponse = $input.first().json.response;

console.log(`Processing task: ${taskData.title}`);

// Parse AI response
let enhancedData;
try {
  const jsonMatch = aiResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    enhancedData = JSON.parse(jsonMatch[0]);
    console.log('AI JSON parsed successfully');
  } else {
    throw new Error('No JSON found');
  }
} catch (error) {
  console.log('Using fallback enhancement');
  enhancedData = {
    description: `Enhanced: ${taskData.title}. This task requires proper planning and execution.`,
    complexity: 3,
    tags: ['ai-enhanced', 'auto-generated', 'todo']
  };
}

// Prepare update data
const result = {
  task_id: taskData.task_id,
  enhanced_description: `${enhancedData.description}\n\n🤖 AI Enhancement Applied\n📊 Complexity: ${enhancedData.complexity}/5\n🏷️ Tags: ${enhancedData.tags.join(', ')}`
};

console.log(`Ready to update task ${result.task_id}`);
return { json: result };
